first=sha(R/'report.json');sma=sha(R/'forward_report.json');assert first==b['first_financial_report_sha256'] and sma==b['first_SMA_report_sha256']
file=R/'next_research_state.json';before=rd(file);oldhash=sha(file);after=copy.deepcopy(before);h=after['UTC_midnight_handoff'];entries=h['next_window_known_actual_funding_sources']
for e in entries:
 doc=rd(ROOT/e['path']);assert sha(ROOT/e['path'])==e['sha256'] and doc['recorded_utc']==e['original_capture_utc'] and doc['public_fields_by_asset']==e['actual_public_fields']
contract={'required_before_any_next_reserve':True,'source':'readonly_recovery_binding.json','audit_axis_failure_this_round_retained':{'phase':'audit','native_exit_code':1,'effective_readonly_phase':'audit_exit_axes','effective_native_exit_code':0},'axis_consumer_guard':'Before any next reserve, statically verify all frozen plan axis labels used by run.py, audit.py, exports.py, definitions.py and sizing_units.py. Adapt original audit.py to the next preset before binding; do not transplant this round recovery wrapper without its own full immutable binding. Keep four original constant-key fixes distinct from actual model rules.','all_known_actual_funding_sources_count':len(entries),'funding_prebinding_guard':'Refresh and bind EVERY retained first actual funding source, including newly unbooked next-window source(s), exact original UTC/time/rate/mark/raw SHA and each own chain. Do not retain a hardcoded six-source assertion when there are more entries. Book only the next own covered window from original q, never copy cashflows or settle early.','sources_metadata':[{k:e[k] for k in ['path','sha256','original_capture_utc','actual_timestamp_ns','current_own_booked_counts','next_own_coverage_expected_counts']} for e in entries],'current_cashflow_collector_guard':'Before next reserve, adapt the readonly collector to resolve each actual journal settlement by its exact timestamp from ALL bound first sources, not the old fixed Nov25_00 lookup. The next L4/FEWM window can contain Nov25_08 while C does not; use each own original signed q and exact current expected counts. Never replay prior settlements.', 'new_strategy_account_or_cashflow_evaluations':0}
assert 'next_pre_reserve_validation_contract' not in after;after['next_pre_reserve_validation_contract']=contract;check=copy.deepcopy(after);check.pop('next_pre_reserve_validation_contract');assert check==before;put(file,after)
md=R/'result.md';oldmd=sha(md);text=md.read_text();text+='\n审计失败与恢复：原audit.py仍引用旧波动窗轴名，独立检查退出1，原始回执与代码原样保留。另行绑定audit_exit_axes.py/readonly_recovery.py，仅替换四个AST字符串键，复核退出0；collect/checks仅适配真实失败回执的显式恢复规则。首份金融与SMA报告、原冻结代码及已完成账户未改写，金融计算和每个账户窗口均只执行一次。后续检查不能把原退出1改称0，详见readonly_recovery_binding.json及逐阶段验证。\n'
text+=f'\n下一轮在任何reserve之前，必须将全部轴消费者与新预定参数轴静态核对，并逐项绑定当前保存的全部{len(entries)}个实际资金费首次来源；不能沿用仅六来源的数量断言。各账户待处理计数仍以实际时间窗口为准，本轮未提前计入。退出缓冲九格实际desired/成交/全成本NAV一致，是本段历史未区分这些阈值的证据，不能视为新增独立alpha或已证明未来稳健。\n';md.write_text(text)
for p,hv in b['immutable_inputs_sha256'].items():assert sha(ROOT/p)==hv
assert sha(R/'report.json')==first and sha(R/'forward_report.json')==sma
put(R/'recovery_handoff_verification.json',{'passed':True,'recorded_utc':datetime.now(timezone.utc).isoformat(),'source_sha256':b['source_sha256'],'original_audit_exit_code':1,'effective_readonly_audit_exit_code':0,'all_old_next_state_fields_unchanged':True,'next_state_before_sha256':oldhash,'next_state_after_sha256':sha(file),'result_before_sha256':oldmd,'result_after_sha256':sha(md),'all_first_sources_count':len(entries),'financial_report_sha256_unchanged':first,'SMA_report_sha256_unchanged':sma,'new_strategy_account_or_cashflow_evaluations':0});print('PASS truthful audit1/effective0 recovery and all',len(entries),'first-source next-reserve contract; no model/account execution')
